// --- COMPLIANCE FLOW DIAGRAM ---
export const ComplianceFlowDiagram: React.FC = () => {
  const [step, setStep] = useState(0);

  useEffect(() => {
    const interval = setInterval(() => {
        setStep(s => (s + 1) % 4);
    }, 2500);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="flex flex-col items-center p-8 bg-stone-900/50 rounded-xl border border-stone-800 my-8">
      <h3 className="font-serif text-xl mb-4 text-white">The Compliance Life Cycle</h3>
      <p className="text-sm text-stone-400 mb-6 text-center max-w-md">
        Our proprietary process ensures every transaction is mapped, verified, and filed with absolute precision.
      </p>

      <div className="relative w-full max-w-lg h-56 bg-stone-800 rounded-lg shadow-inner overflow-hidden mb-6 border border-stone-700 flex items-center justify-center gap-8 p-4">

        {/* Data Input */}
        <div className="flex flex-col items-center gap-2">
            <div className={`w-16 h-16 rounded-lg border-2 flex flex-col items-center justify-center transition-colors duration-500 ${step === 0 ? 'border-corporate-light bg-corporate-light/10' : 'border-stone-700 bg-stone-900'}`}>
                <div className="grid grid-cols-2 gap-1">
                    {[...Array(4)].map((_, i) => <div key={i} className={`w-3 h-1 rounded ${step === 0 ? 'bg-corporate-light' : 'bg-stone-700'}`}></div>)}
                </div>
            </div>
            <span className="text-[10px] uppercase font-bold tracking-wider text-stone-500">Vouchers</span>
        </div>

        <motion.div animate={{ opacity: step >= 1 ? 1 : 0.3, x: step >= 1 ? 0 : -5 }} className="text-stone-600">→</motion.div>

        {/* Audit Stage */}
        <div className="flex flex-col items-center gap-2">
             <div className={`w-24 h-24 rounded-xl border-2 flex flex-col items-center justify-center gap-2 transition-colors duration-500 relative overflow-hidden ${step === 1 || step === 2 ? 'border-white bg-corporate-blue text-white' : 'border-stone-700 bg-stone-900'}`}>
                <CheckCircle2 size={24} className={step === 1 || step === 2 ? 'text-white animate-pulse' : 'text-stone-700'} />
                {step === 1 && (
                    <div className="absolute inset-0 flex items-center justify-center">
                        <div className="w-full h-[1px] bg-white/30 absolute top-1/3 animate-ping"></div>
                        <div className="w-full h-[1px] bg-white/30 absolute top-2/3 animate-ping delay-75"></div>
                    </div>
                )}
             </div>
             <span className="text-[10px] uppercase font-bold tracking-wider text-stone-500">Verification</span>
        </div>

        <motion.div animate={{ opacity: step >= 3 ? 1 : 0.3, x: step >= 3 ? 0 : -5 }} className="text-stone-600">→</motion.div>

        {/* Filing Stage */}
        <div className="flex flex-col items-center gap-2">
            <div className={`w-16 h-16 rounded-lg border-2 flex flex-col items-center justify-center transition-colors duration-500 ${step === 3 ? 'border-green-400 bg-green-900/30' : 'border-stone-700 bg-stone-900'}`}>
                {step === 3 ? (
                    <div className="flex flex-col items-center">
                         <FileText size={20} className="text-green-400" />
                         <span className="text-[8px] font-bold text-green-400 mt-1">FILED</span>
                    </div>
                ) : (
                    <span className="text-2xl font-serif text-stone-700">?</span>
                )}
            </div>
            <span className="text-[10px] uppercase font-bold tracking-wider text-stone-500">Statutory Return</span>
        </div>

      </div>

      <div className="flex gap-2">
          {[0, 1, 2, 3].map(s => (
              <div key={s} className={`h-1 rounded-full transition-all duration-300 ${step === s ? 'w-8 bg-corporate-light' : 'w-2 bg-stone-700'}`}></div>
          ))}
      </div>
    </div>
  );
};

