import React, { useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Float, MeshDistortMaterial, Sphere, Torus, Cylinder, Stars, Environment, Box } from '@react-three/drei';
import * as THREE from 'three';

// Fix for JSX intrinsic element errors by defining them as local components.
// These satisfy TypeScript's strict check on JSX.IntrinsicElements while remaining compatible with @react-three/fiber.
const MeshStandardMaterial = 'meshStandardMaterial' as any;
const AmbientLight = 'ambientLight' as any;
const PointLight = 'pointLight' as any;
const SpotLight = 'spotLight' as any;
const Group = 'group' as any;

const BusinessNode = ({ position, color, scale = 1 }: { position: [number, number, number]; color: string; scale?: number }) => {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      ref.current.position.y = position[1] + Math.sin(t * 1.5 + position[0]) * 0.15;
      ref.current.rotation.x = t * 0.2;
      ref.current.rotation.z = t * 0.1;
    }
  });

  return (
    <Sphere ref={ref} args={[1, 32, 32]} position={position} scale={scale}>
      <MeshDistortMaterial
        color={color}
        envMapIntensity={0.8}
        clearcoat={0.5}
        clearcoatRoughness={0.1}
        metalness={0.8}
        roughness={0.2}
        distort={0.3}
        speed={1.5}
      />
    </Sphere>
  );
};

const ConnectivityRing = ({ color = "#003366" }) => {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (ref.current) {
       const t = state.clock.getElapsedTime();
       ref.current.rotation.x = Math.sin(t * 0.1) * 0.1;
       ref.current.rotation.y = t * 0.05;
    }
  });

  return (
    <Torus ref={ref} args={[3, 0.02, 16, 100]} rotation={[Math.PI / 2, 0, 0]}>
      {/* Replaced meshStandardMaterial with PascalCase constant */}
      <MeshStandardMaterial color={color} emissive={color} emissiveIntensity={0.2} transparent opacity={0.4} />
    </Torus>
  );
}

