// --- Scroll Section Component ---
// Defines a reusable motion section for scroll reveal animations.
const ScrollSection: React.FC<{ children: React.ReactNode; className?: string }> = ({ children, className }) => {
  return (
    <motion.section
      initial={{ opacity: 0, y: 50 }}
      whileInView={{ opacity: 1, y: 0 }}
      viewport={{ once: true, margin: "-100px" }}
      transition={{ duration: 1, ease: [0.22, 1, 0.36, 1] }}
      className={className}
    >
      {children}
    </motion.section>
  );
};

// --- Chatbot Component ---
const AIChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: 'Hello! I am the Win-Win Advisor. How can I assist you with your business accounting, audit, or tax questions today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input;
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsTyping(true);

    try {
      // Correctly initializing GoogleGenAI with a named parameter.
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: "You are the Win-Win Assistant for 'Win-Win Business Solutions Pvt. Ltd.', a professional accounting and audit firm in Madurai, Tamil Nadu. Your expertise includes GST compliance, Statutory Audit, Income Tax filing, FEMA, Company Incorporation (Pvt Ltd, LLP, OPC), and Funding Advisory. Be professional, concise, and helpful. Prioritize firm-specific knowledge but use general AI knowledge for complex tax logic if needed. Firm CIN: U7499TN2022PTC152948. Firm GSTIN: 33AADCW2822J1ZF.",
          temperature: 0.7,
        },
      });

      // Accessing response.text as a property, not a method.
      setMessages(prev => [...prev, { role: 'ai', text: response.text || "I apologize, but I am unable to process that request at the moment." }]);
    } catch (error) {
      console.error(error);
      setMessages(prev => [...prev, { role: 'ai', text: "I'm having trouble connecting to my knowledge base. Please try again or contact our office directly." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200] chatbot">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 20, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 20, scale: 0.95 }}
            className="mb-4 w-[350px] h-[500px] bg-white dark:bg-stone-900 shadow-2xl rounded-3xl border border-stone-100 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            <div className="p-6 bg-corporate-blue text-white flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center font-bold">W</div>
                <div>
                   <h3 className="text-sm font-bold">Win-Win Advisor</h3>
                   <p className="text-[10px] opacity-70">AI-Powered Consultant</p>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)}><X size={20}/></button>
            </div>

            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[80%] p-4 rounded-2xl text-sm ${m.role === 'user' ? 'bg-corporate-blue text-white rounded-tr-none' : 'bg-stone-100 dark:bg-stone-800 text-stone-700 dark:text-stone-300 rounded-tl-none'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className="bg-stone-100 dark:bg-stone-800 p-4 rounded-2xl flex items-center gap-2">
                    <Loader2 className="animate-spin text-corporate-blue" size={16} />
                    <span className="text-xs">Thinking...</span>
                  </div>
                </div>
              )}
            </div>

            <div className="p-4 border-t dark:border-stone-800 flex gap-2">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask about GST, Audit, or Company Formation..."
                className="flex-1 bg-stone-50 dark:bg-stone-950 border-none rounded-full px-4 text-sm focus:ring-2 focus:ring-corporate-blue outline-none"
              />
              <button 
                onClick={handleSend}
                disabled={isTyping}
                className="w-10 h-10 bg-corporate-blue text-white rounded-full flex items-center justify-center hover:bg-corporate-navy transition-colors disabled:opacity-50"
              >
                <Send size={18} />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <motion.button
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(!isOpen)}
        className="w-16 h-16 bg-corporate-blue text-white rounded-full shadow-2xl flex items-center justify-center"
      >
        {isOpen ? <ChevronDown /> : <MessageSquare />}
      </motion.button>
    </div>
  );
};

