// --- Chatbot Component ---
const AIChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: 'Hello! I am the Win-Win Advisor. How can I assist you with your professional accounting, audit, or incorporation needs today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input;
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: "You are the Win-Win Advisor, an AI representative of Win-Win Business Solutions Pvt. Ltd. Your tone is executive, professional, and reliable. Answer questions about Accounting, Audits, GST, Income Tax, FEMA, and Company Registration based on the firm's expertise. Firm Location: Madurai. CIN: U7499TN2022PTC152948. Be helpful but encourage users to book a strategic session for complex legal matters.",
          temperature: 0.7,
        },
      });

      setMessages(prev => [...prev, { role: 'ai', text: response.text || "I apologize, I'm having trouble processing that right now." }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service temporarily unavailable. Please call us at +91 90802 11105." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200] chatbot">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 30, scale: 0.9 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 30, scale: 0.9 }}
            className="mb-4 w-[360px] h-[520px] bg-white dark:bg-stone-900 shadow-2xl rounded-3xl border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            <div className="p-6 bg-corporate-blue text-white flex justify-between items-center shadow-lg">
              <div className="flex items-center gap-3">
                <div className="w-10 h-10 bg-white/20 rounded-full flex items-center justify-center font-bold text-lg">W</div>
                <div>
                   <h3 className="text-sm font-black tracking-tight">Win-Win Advisor</h3>
                   <div className="flex items-center gap-1">
                      <div className="w-1.5 h-1.5 bg-green-400 rounded-full animate-pulse" />
                      <p className="text-[10px] opacity-70">Active Professional AI</p>
                   </div>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)} className="hover:rotate-90 transition-transform"><X size={20}/></button>
            </div>

            <div ref={scrollRef} className="flex-1 overflow-y-auto p-5 space-y-4 no-scrollbar bg-stone-50 dark:bg-stone-950/30">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-4 rounded-2xl text-sm shadow-sm ${m.role === 'user' ? 'bg-corporate-blue text-white rounded-tr-none' : 'bg-white dark:bg-stone-800 text-stone-700 dark:text-stone-300 border dark:border-stone-700 rounded-tl-none'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className="bg-white dark:bg-stone-800 p-4 rounded-2xl flex items-center gap-3 shadow-sm border dark:border-stone-700">
                    <Loader2 className="animate-spin text-corporate-blue" size={16} />
                    <span className="text-xs font-medium">Analyzing...</span>
                  </div>
                </div>
              )}
            </div>

            <div className="p-5 border-t dark:border-stone-800 flex gap-2 bg-white dark:bg-stone-900">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask about GST, Audit, or Taxation..."
                className="flex-1 bg-stone-100 dark:bg-stone-950 border-none rounded-full px-5 py-3 text-sm focus:ring-2 focus:ring-corporate-blue outline-none transition-all"
              />
              <button 
                onClick={handleSend}
                disabled={isTyping || !input.trim()}
                className="w-12 h-12 bg-corporate-blue text-white rounded-full flex items-center justify-center hover:bg-corporate-navy transition-all disabled:opacity-50 disabled:grayscale"
              >
                <Send size={18} />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <motion.button
        whileHover={{ scale: 1.05 }}
        whileTap={{ scale: 0.95 }}
        onClick={() => setIsOpen(!isOpen)}
        className="w-16 h-16 bg-corporate-blue text-white rounded-full shadow-[0_15px_30px_rgba(0,85,164,0.4)] flex items-center justify-center relative overflow-hidden"
      >
        <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/10 to-transparent" />
        {isOpen ? <ChevronDown size={28} /> : <MessageSquare size={28} />}
      </motion.button>
    </div>
  );
};

