// --- Chatbot Component ---
const AIChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: 'Welcome to Win-Win. I am your AI Business Advisor. How can I help you with your accounting or audit questions today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMessage = input;
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: "You are the Win-Win Advisor. You represent Win-Win Business Solutions Pvt. Ltd., Madurai. Your expertise: GST, Audit, ITR, Company Formation, FEMA. Tone: Professional, authoritative, yet encouraging. Help customers understand how Win-Win can grow their business. CIN: U7499TN2022PTC152948. If unsure, suggest booking a consultation.",
          temperature: 0.7,
        },
      });
      setMessages(prev => [...prev, { role: 'ai', text: response.text || "I'm sorry, I couldn't process that. Please contact our office." }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'ai', text: "Connectivity issues. Please reach us at +91 90802 11105." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-8 right-8 z-[200]">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 50, scale: 0.8 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 50, scale: 0.8 }}
            className="mb-4 w-[380px] h-[550px] bg-white dark:bg-stone-900 shadow-2xl rounded-[2.5rem] border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            <div className="p-7 bg-corporate-navy text-white flex justify-between items-center shadow-lg">
              <div className="flex items-center gap-4">
                <div className="w-10 h-10 bg-corporate-light rounded-2xl flex items-center justify-center font-black text-stone-900">W</div>
                <div>
                  <h3 className="font-bold text-sm">Win-Win AI</h3>
                  <p className="text-[10px] opacity-60">Ready to consult</p>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={20}/></button>
            </div>
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-4 no-scrollbar bg-stone-50 dark:bg-stone-950/20">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[85%] p-4 rounded-2xl text-sm leading-relaxed ${m.role === 'user' ? 'bg-corporate-blue text-white rounded-tr-none' : 'bg-white dark:bg-stone-800 text-stone-700 dark:text-stone-300 border dark:border-stone-700 shadow-sm rounded-tl-none'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className="bg-white dark:bg-stone-800 p-4 rounded-2xl flex items-center gap-3 border dark:border-stone-700 shadow-sm">
                    <Loader2 className="animate-spin text-corporate-blue" size={16} />
                    <span className="text-xs font-bold uppercase tracking-widest text-stone-400">Consulting...</span>
                  </div>
                </div>
              )}
            </div>
            <div className="p-5 border-t dark:border-stone-800 flex gap-3 bg-white dark:bg-stone-900">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Type your business query..."
                className="flex-1 bg-stone-100 dark:bg-stone-950 border-none rounded-2xl px-5 py-4 text-sm focus:ring-2 focus:ring-corporate-blue outline-none"
              />
              <button onClick={handleSend} disabled={isTyping} className="w-14 h-14 bg-corporate-navy text-white rounded-2xl flex items-center justify-center hover:bg-corporate-blue transition-all disabled:opacity-50">
                <Send size={20} />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <motion.button
        whileHover={{ scale: 1.05, rotate: 5 }}
        whileTap={{ scale: 0.95 }}
        onClick={() => setIsOpen(!isOpen)}
        className="w-20 h-20 bg-corporate-navy text-white rounded-3xl shadow-[0_20px_40px_rgba(0,0,0,0.3)] flex items-center justify-center relative overflow-hidden group"
      >
        <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/5 to-transparent group-hover:via-white/10 transition-all" />
        {isOpen ? <ChevronDown size={32} /> : <MessageSquare size={32} />}
      </motion.button>
    </div>
  );
};

