const AIChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: 'Greetings. I am the Win-Win Strategic Advisor. How may I assist your corporate governance or fiscal planning today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMessage = input;
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: "You are the Win-Win Advisor. Firm: Win-Win Business Solutions Pvt. Ltd., Madurai. Expertise: Corporate Audit, IndAS, GST, FEMA, Income Tax, Startup Funding. Tone: Highly professional, executive, reliable. Help users understand compliance and strategic growth. CIN: U7499TN2022PTC152948. If the query is complex, suggest a formal discovery session.",
          temperature: 0.7,
        },
      });
      setMessages(prev => [...prev, { role: 'ai', text: response.text || "I apologize, my analysis engine is currently recalibrating. Please contact us directly." }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service temporarily unavailable. Our advisory desk can be reached at +91 90802 11105." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-10 right-10 z-[200]">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 80, scale: 0.8 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 80, scale: 0.8 }}
            className="mb-6 w-[400px] h-[600px] bg-white dark:bg-stone-900 shadow-[0_40px_80px_rgba(0,0,0,0.4)] rounded-[3rem] border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            <div className="p-8 bg-corporate-navy text-white flex justify-between items-center shadow-lg">
              <div className="flex items-center gap-5">
                <div className="w-12 h-12 bg-corporate-light rounded-2xl flex items-center justify-center font-black text-stone-900 shadow-inner">W</div>
                <div>
                  <h3 className="font-black text-lg tracking-tight uppercase">Strategic Advisor</h3>
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                    <p className="text-[10px] uppercase font-bold tracking-widest opacity-60">Engine Active</p>
                  </div>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)} className="p-3 hover:bg-white/10 rounded-full transition-all hover:rotate-90"><X size={24}/></button>
            </div>
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-8 space-y-6 no-scrollbar bg-stone-50 dark:bg-stone-950/20">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-5 rounded-[2rem] text-sm leading-relaxed shadow-sm ${m.role === 'user' ? 'bg-corporate-blue text-white rounded-tr-none' : 'bg-white dark:bg-stone-800 text-stone-700 dark:text-stone-300 border dark:border-stone-700 rounded-tl-none'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className="bg-white dark:bg-stone-800 p-5 rounded-[2rem] flex items-center gap-4 border dark:border-stone-700 shadow-sm">
                    <Loader2 className="animate-spin text-corporate-blue" size={20} />
                    <span className="text-[10px] font-black uppercase tracking-[0.2em] text-stone-400">Synthesizing...</span>
                  </div>
                </div>
              )}
            </div>
            <div className="p-6 border-t dark:border-stone-800 flex gap-4 bg-white dark:bg-stone-900">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Submit inquiry..."
                className="flex-1 bg-stone-100 dark:bg-stone-950 border-none rounded-2xl px-6 py-5 text-sm focus:ring-4 focus:ring-corporate-blue/10 outline-none transition-all"
              />
              <button onClick={handleSend} disabled={isTyping} className="w-16 h-16 bg-corporate-navy text-white rounded-2xl flex items-center justify-center hover:bg-corporate-blue transition-all disabled:opacity-50 shadow-xl">
                <Send size={24} />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <motion.button
        whileHover={{ scale: 1.1, rotate: 5, boxShadow: "0 25px 50px rgba(0,26,51,0.5)" }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(!isOpen)}
        className="w-24 h-24 bg-corporate-navy text-white rounded-[2rem] shadow-[0_20px_40px_rgba(0,0,0,0.3)] flex items-center justify-center relative overflow-hidden group"
