);

const AIChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: 'Greetings. I am the Win-Win Strategic Advisor. How may I assist your corporate governance or fiscal planning today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMessage = input;
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setInput('');
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: "You are the Win-Win Advisor. Firm: Win-Win Business Solutions Pvt. Ltd., Madurai. Expertise: Corporate Audit, IndAS, GST, FEMA, Income Tax, Startup Funding. Tone: Highly professional, executive, reliable. Help users understand compliance and strategic growth. CIN: U7499TN2022PTC152948. If the query is complex, suggest a formal discovery session.",
