const AIChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'user' | 'ai'; text: string }[]>([
    { role: 'ai', text: 'Good day. I am the Win-Win Strategic Advisor. How can I assist you with your business compliance or financial strategy today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const userMsg = input;
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsTyping(true);

    try {
      // Always initialize the client with process.env.API_KEY as per the requirements.
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      // GenerateContentResponse is accessed to handle the AI response correctly.
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMsg,
        config: {
          systemInstruction: "You are the Win-Win Advisor. Firm: Win-Win Business Solutions Pvt. Ltd., Madurai. Expertise: Corporate Audit, GST, FEMA, Income Tax, Startup Strategy. Tone: Executive, precise, helpful. CIN: U7499TN2022PTC152948. Encourage formal consultations for deep legal matters.",
          temperature: 0.7,
        },
      });
      // Directly access response.text property (not a method).
      setMessages(prev => [...prev, { role: 'ai', text: response.text || "I'm sorry, I'm unable to process that query right now." }]);
    } catch (e) {
      setMessages(prev => [...prev, { role: 'ai', text: "Service temporary unavailable. Please reach us at admin@win-win.co.in" }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-12 right-12 z-[250]">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, y: 100, scale: 0.8 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 100, scale: 0.8 }}
            className="mb-6 w-[400px] h-[600px] bg-white dark:bg-stone-900 shadow-[0_40px_100px_rgba(0,0,0,0.5)] rounded-[3.5rem] border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            <div className="p-10 bg-corporate-navy text-white flex justify-between items-center shadow-2xl">
              <div className="flex items-center gap-5">
                <div className="w-12 h-12 bg-corporate-light rounded-2xl flex items-center justify-center font-black text-stone-900 shadow-inner">W</div>
                <div>
                  <h3 className="font-black text-sm uppercase tracking-widest">Win-Win AI</h3>
                  <div className="flex items-center gap-2">
                    <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" />
                    <p className="text-[9px] uppercase font-bold tracking-widest opacity-50">Strategic Engine Live</p>
                  </div>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)} className="p-3 hover:bg-white/10 rounded-full transition-all hover:rotate-90"><X size={24}/></button>
            </div>
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-8 no-scrollbar bg-stone-50 dark:bg-stone-950/20">
              {messages.map((m, i) => (
                <div key={i} className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                  <div className={`max-w-[90%] p-6 rounded-[2.5rem] text-sm leading-relaxed ${m.role === 'user' ? 'bg-corporate-blue text-white rounded-tr-none shadow-xl' : 'bg-white dark:bg-stone-800 text-stone-700 dark:text-stone-300 border dark:border-stone-700 rounded-tl-none shadow-sm'}`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                  <div className="bg-white dark:bg-stone-800 p-6 rounded-[2rem] flex items-center gap-4 border dark:border-stone-700 shadow-sm">
                    <Loader2 className="animate-spin text-corporate-blue" size={20} />
