                  </div>
                </div>
              )}
            </div>
            <div className="p-8 border-t dark:border-stone-800 flex gap-4 bg-white dark:bg-stone-900">
              <input 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask our AI advisor..."
                className="flex-1 bg-stone-100 dark:bg-stone-950 border-none rounded-2xl px-8 py-5 text-sm focus:ring-4 focus:ring-corporate-blue/10 outline-none"
              />
              <button onClick={handleSend} disabled={isTyping} className="w-16 h-16 bg-corporate-navy text-white rounded-2xl flex items-center justify-center hover:bg-corporate-blue transition-all disabled:opacity-50">
                <Send size={24} />
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
      <motion.button
        whileHover={{ scale: 1.1, rotate: -5, boxShadow: "0 25px 50px rgba(0,26,51,0.5)" }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(!isOpen)}
        className="w-24 h-24 bg-corporate-navy text-white rounded-[2.5rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] flex items-center justify-center relative group"
      >
        <div className="absolute inset-0 bg-gradient-to-tr from-transparent via-white/10 to-transparent group-hover:via-white/20 transition-all" />
        {isOpen ? <ChevronDown size={36} /> : <MessageSquare size={36} />}
      </motion.button>
    </div>
  );
};

