import React, { useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Float, MeshDistortMaterial, Sphere, Torus, Environment, Stars, Box } from '@react-three/drei';
import * as THREE from 'three';

const MeshStandardMaterial = 'meshStandardMaterial' as any;
const AmbientLight = 'ambientLight' as any;
const PointLight = 'pointLight' as any;
const Group = 'group' as any;

const GlassOrb = ({ position, color, scale = 1 }: { position: [number, number, number]; color: string; scale?: number }) => {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      ref.current.position.y = position[1] + Math.sin(t * 0.5 + position[0]) * 0.1;
      ref.current.rotation.y = t * 0.1;
    }
  });

  return (
    <Sphere ref={ref} args={[1, 64, 64]} position={position} scale={scale}>
      <MeshDistortMaterial
        color={color}
        speed={1}
        distort={0.1}
        radius={1}
        metalness={0.9}
        roughness={0.05}
        transparent
        opacity={0.8}
        transmission={1}
        thickness={2}
      />
    </Sphere>
  );
};

const LatticeFrame = () => {
  const ref = useRef<THREE.Mesh>(null);
  useFrame((state) => {
    if (ref.current) {
      ref.current.rotation.y = state.clock.getElapsedTime() * 0.05;
    }
  });

  return (
    <Group ref={ref}>
       <Torus args={[4, 0.01, 16, 100]} rotation={[Math.PI/2, 0, 0]}>
         <MeshStandardMaterial color="#B59E6D" emissive="#B59E6D" emissiveIntensity={0.2} />
       </Torus>
       <Torus args={[3.8, 0.005, 16, 100]} rotation={[0, Math.PI/2, 0]}>
         <MeshStandardMaterial color="#B59E6D" emissive="#B59E6D" emissiveIntensity={0.1} />
       </Torus>
    </Group>
  );
};

export const HeroScene: React.FC = () => {
  return (
    <div className="w-full h-full">
      <Canvas camera={{ position: [0, 0, 8], fov: 35 }}>
        <AmbientLight intensity={0.5} />
        <PointLight position={[10, 10, 10]} intensity={1} />
        <Environment preset="night" />

        <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.5}>
          <GlassOrb position={[0, 0, 0]} color="#002B5B" scale={1.5} />
          <LatticeFrame />
        </Float>

        <Stars radius={100} depth={50} count={1000} factor={4} saturation={0} fade speed={1} />
      </Canvas>
    </div>
  );
};

export const CorporateNetworkScene: React.FC = () => {
  return (
