        <PointLight position={[5, 5, 5]} intensity={1} />
        <Float speed={0.5} rotationIntensity={0.1}>
          <Box args={[2, 2, 2]} wireframe>
            <MeshStandardMaterial color="#B59E6D" transparent opacity={0.2} />
          </Box>
        </Float>
      </Canvas>
    </div>
  );
