import React, { useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Float, MeshDistortMaterial, Sphere, Torus, Environment, Stars } from '@react-three/drei';
import * as THREE from 'three';

const MeshStandardMaterial = 'meshStandardMaterial' as any;
const AmbientLight = 'ambientLight' as any;
const PointLight = 'pointLight' as any;
const Group = 'group' as any;

const GlassOrb = ({ position, color, scale = 1 }: { position: [number, number, number]; color: string; scale?: number }) => {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      ref.current.position.y = position[1] + Math.sin(t * 0.5 + position[0]) * 0.15;
      ref.current.rotation.y = t * 0.2;
    }
  });

  return (
    <Sphere ref={ref} args={[1, 64, 64]} position={position} scale={scale}>
      <MeshDistortMaterial
        color={color}
        speed={1}
        distort={0.15}
        radius={1}
        metalness={0.9}
        roughness={0.05}
        transparent
        opacity={0.7}
        transmission={1}
        thickness={2}
      />
    </Sphere>
  );
};

const LatticeFrame = () => {
  const ref = useRef<THREE.Mesh>(null);
  useFrame((state) => {
    if (ref.current) {
      ref.current.rotation.y = state.clock.getElapsedTime() * 0.08;
      ref.current.rotation.z = Math.sin(state.clock.getElapsedTime() * 0.2) * 0.1;
    }
  });

  return (
    <Group ref={ref}>
       <Torus args={[4, 0.005, 16, 100]} rotation={[Math.PI/2, 0, 0]}>
         <MeshStandardMaterial color="#B59E6D" emissive="#B59E6D" emissiveIntensity={0.5} />
       </Torus>
       <Torus args={[3.8, 0.002, 16, 100]} rotation={[0, Math.PI/2, 0]}>
         <MeshStandardMaterial color="#B59E6D" emissive="#B59E6D" emissiveIntensity={0.3} />
       </Torus>
    </Group>
  );
};

export const HeroScene: React.FC = () => {
  return (
    <div className="w-full h-full">
      <Canvas camera={{ position: [0, 0, 8], fov: 35 }}>
        <AmbientLight intensity={0.5} />
        <PointLight position={[10, 10, 10]} intensity={1} />
        <Environment preset="night" />

        <Float speed={2} rotationIntensity={0.5} floatIntensity={0.5}>
          <GlassOrb position={[0, 0, 0]} color="#002B5B" scale={1.8} />
          <LatticeFrame />
        </Float>

        <Stars radius={100} depth={50} count={2000} factor={4} saturation={0} fade speed={1} />
      </Canvas>
    </div>
  );
};

export const CorporateNetworkScene: React.FC = () => {
  return (
    <div className="w-full h-full opacity-30">
      <Canvas camera={{ position: [0, 0, 5], fov: 45 }}>
        <AmbientLight intensity={1} />
        <PointLight position={[5, 5, 5]} intensity={1} />
        <Float speed={1} rotationIntensity={0.5}>
          <Torus args={[2, 0.01, 16, 100]} rotation={[Math.PI/4, 0, 0]}>
            <MeshStandardMaterial color="#B59E6D" />
          </Torus>
        </Float>
      </Canvas>
    </div>
  );
};

