import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageSquare, X, Send, Bot, User, Loader2 } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

export const AIChatbot: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'bot' | 'user'; text: string }[]>([
    { role: 'bot', text: 'Welcome to the Win-Win Advisory Studio. How may I assist your corporate strategy today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: `You are the Win-Win Senior Financial Architect. 
          Your tone is institutional, precise, and authoritative. 
          You represent Win-Win Business Solutions Pvt Ltd. 
          Expertise: Accounting, Statutory Audit, FEMA, GST, Taxation, and Corporate Structure.
          Answer concisely. If asked about non-financial topics, politely steer back to corporate advisory.
          Use Markdown for clarity.`,
          temperature: 0.7,
        },
      });

      const botText = response.text || "I apologize, but I am unable to process that specific advisory request at this moment. Please contact our senior partners at admin@win-win.co.in.";
      setMessages(prev => [...prev, { role: 'bot', text: botText }]);
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'bot', text: "A connection disruption occurred. Please try again or contact our main desk." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-8 right-8 z-[200]">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            className="absolute bottom-20 right-0 w-[350px] md:w-[400px] h-[500px] bg-white dark:bg-stone-900 rounded-[2.5rem] shadow-2xl border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            {/* Header */}
            <div className="p-6 bg-corporate-blue text-white flex justify-between items-center">
              <div className="flex items-center gap-3">
                <div className="p-2 bg-white/10 rounded-lg">
                  <Bot size={20} />
                </div>
                <div>
                  <h4 className="text-xs font-black uppercase tracking-[0.2em]">Advisory Bot</h4>
                  <div className="flex items-center gap-1">
                    <div className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse" />
                    <span className="text-[9px] opacity-60 uppercase tracking-widest">Active Studio</span>
                  </div>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors">
                <X size={18} />
              </button>
            </div>

            {/* Chat Messages */}
            <div 
              ref={scrollRef}
              className="flex-1 overflow-y-auto p-6 space-y-4 custom-scrollbar bg-stone-50/50 dark:bg-stone-950/20"
            >
              {messages.map((m, i) => (
                <motion.div 
                  key={i}
                  initial={{ opacity: 0, x: m.role === 'user' ? 10 : -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  className={`flex ${m.role === 'user' ? 'justify-end' : 'justify-start'}`}
                >
                  <div className={`max-w-[80%] p-4 rounded-2xl text-xs leading-relaxed ${
                    m.role === 'user' 
                      ? 'bg-corporate-gold text-white rounded-tr-none shadow-md' 
                      : 'bg-white dark:bg-stone-800 text-stone-700 dark:text-stone-300 border dark:border-stone-700 rounded-tl-none shadow-sm'
                  }`}>
                    {m.text}
                  </div>
                </motion.div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-white dark:bg-stone-800 p-4 rounded-2xl rounded-tl-none border dark:border-stone-700 flex items-center gap-2">
                      <Loader2 size={14} className="animate-spin text-corporate-gold" />
                      <span className="text-[10px] uppercase tracking-widest text-stone-400">Architecting...</span>
                   </div>
                </div>
              )}
            </div>

            {/* Input */}
            <div className="p-4 bg-white dark:bg-stone-900 border-t dark:border-stone-800 flex gap-2">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask an advisory question..."
                className="flex-1 bg-stone-100 dark:bg-stone-800 border-none rounded-full px-5 py-3 text-xs focus:ring-1 focus:ring-corporate-gold outline-none"
              />
              <motion.button 
                whileTap={{ scale: 0.9 }}
                onClick={handleSend}
                disabled={isTyping}
                className="p-3 bg-corporate-blue text-white rounded-full hover:bg-corporate-gold transition-colors disabled:opacity-50"
              >
                <Send size={16} />
              </motion.button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <motion.button
        whileHover={{ scale: 1.1, rotate: -5 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(!isOpen)}
        className="w-16 h-16 bg-corporate-blue text-white rounded-full shadow-2xl flex items-center justify-center hover:bg-corporate-gold transition-all duration-500 border-4 border-white/10"
      >
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </motion.button>
    </div>
  );
};

