);

const App: React.FC = () => {
  const [currentPage, setCurrentPage] = useState<Page>('home');
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);

  const { scrollYProgress } = useScroll({
    target: containerRef,
    offset: ["start start", "end end"]
  });

  const smoothProgress = useSpring(scrollYProgress, { stiffness: 60, damping: 25, restDelta: 0.001 });

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const toggleTheme = () => {
    setIsDarkMode(!isDarkMode);
    document.documentElement.classList.toggle('dark');
  };

  const navigateTo = (page: Page) => {
    setCurrentPage(page);
    setMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  // Fixed transition type error by adding 'as const' to ensure 'spring' is a literal type
  const springConfig = { type: "spring" as const, stiffness: 400, damping: 30 };

  return (
    <div ref={containerRef} className={`relative bg-corporate-stone dark:bg-stone-950 transition-colors duration-1000 ${currentPage === 'home' ? 'min-h-[600vh]' : 'min-h-screen'}`}>

      {/* Editorial Navigation */}
      <nav className={`fixed top-0 left-0 right-0 z-[100] p-6 md:p-8 flex justify-between items-center transition-all duration-500 ${scrolled ? 'bg-white/80 dark:bg-stone-950/80 backdrop-blur-md py-4' : 'bg-transparent'}`}>
        <motion.div 
          whileHover={{ scale: 1.05 }}
          whileTap={{ scale: 0.95 }}
          className="flex items-center gap-4 cursor-pointer mix-blend-difference" 
          onClick={() => navigateTo('home')}
        >
          <div className="w-10 h-10 bg-white text-corporate-blue font-serif font-bold text-xl flex items-center justify-center rounded-lg shadow-xl">W</div>
          <span className="text-white font-serif text-lg tracking-[0.2em] font-bold uppercase hidden sm:block">Win-Win</span>
        </motion.div>

        <div className="flex items-center gap-8 pointer-events-auto mix-blend-difference">
          {['ABOUT', 'SERVICES', 'ENTITIES', 'CONTACT'].map(item => (
            <motion.button 
              key={item} 
              whileHover={{ y: -2, color: '#B59E6D' }}
              transition={springConfig}
              onClick={() => navigateTo(item.toLowerCase() as any)} 
              className="text-white text-[9px] font-black tracking-[0.3em] uppercase transition-colors"
            >
              {item}
            </motion.button>
          ))}
          <motion.button 
            whileHover={{ scale: 1.2, rotate: 10 }}
            whileTap={{ scale: 0.8 }}
            onClick={toggleTheme} 
            className="text-white hover:text-corporate-gold transition-colors"
          >
            {isDarkMode ? <Sun size={16}/> : <Moon size={16}/>}
          </motion.button>
        </div>
      </nav>

      <main>
        <AnimatePresence mode="wait">
          {currentPage === 'home' && (
