import { MessageSquare, X, Send, Bot, Loader2, Calendar } from 'lucide-react';
import { GoogleGenAI } from "@google/genai";

interface AIChatbotProps {
  onActionRequested?: () => void;
}

export const AIChatbot: React.FC<AIChatbotProps> = ({ onActionRequested }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'bot' | 'user'; text: string; hasAction?: boolean }[]>([
    { role: 'bot', text: 'Welcome to the Win-Win Advisory Studio. I am your Senior Financial Architect. How may I assist your corporate strategy today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: `You are the Win-Win Senior Financial Architect. 
          Tone: Institutional, precise, calm, and highly professional.
          Company: Win-Win Business Solutions Pvt Ltd (Madurai).
          Services: Accounting, Statutory Audit, FEMA, GST, Corporate Structuring.
          Constraints: Be concise. If the user asks non-professional questions, politely pivot back to corporate advisory.
          Use bullet points for lists. Always maintain a fiduciary persona.`,
          temperature: 0.6,
        },
      });

      const botText = response.text || "I apologize, but I am unable to process that specific advisory request at this moment.";
      setMessages(prev => [...prev, { role: 'bot', text: botText, hasAction: true }]);
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'bot', text: "A connection disruption occurred. Please try again or reach out to our main desk." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200]">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
