                    <div className="w-1 h-1 rounded-full bg-green-400 animate-pulse" />
                    <span className="text-[8px] opacity-60 uppercase tracking-widest">Architect Active</span>
                  </div>
                </div>
              </div>
              <motion.button 
                whileHover={{ rotate: 90 }}
                onClick={() => setIsOpen(false)} 
                className="p-1 hover:bg-white/10 rounded-full transition-colors"
              >
                <X size={16} />
              </motion.button>
            </div>

            {/* Chat Messages */}
            <div 
              ref={scrollRef}
              className="flex-1 overflow-y-auto p-5 space-y-4 bg-stone-50/50 dark:bg-stone-950/20"
            >
              {messages.map((m, i) => (
                <motion.div 
                  key={i}
                  initial={{ opacity: 0, x: m.role === 'user' ? 10 : -10 }}
                  animate={{ opacity: 1, x: 0 }}
                  className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}
                >
                  <div className={`max-w-[85%] p-3.5 rounded-2xl text-[11px] leading-relaxed ${
                    m.role === 'user' 
