                </div>
              )}
            </div>

            {/* Input */}
            <div className="p-3 bg-white dark:bg-stone-900 border-t dark:border-stone-800 flex gap-2">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Ask an advisory question..."
                className="flex-1 bg-stone-100 dark:bg-stone-800 border-none rounded-full px-4 py-2.5 text-[11px] focus:ring-1 focus:ring-corporate-gold outline-none"
              />
              <motion.button 
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={handleSend}
                disabled={isTyping}
                className="p-2.5 bg-corporate-blue text-white rounded-full hover:bg-corporate-gold transition-colors disabled:opacity-50"
              >
                <Send size={14} />
              </motion.button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <motion.button
        whileHover={{ scale: 1.1, rotate: -5 }}
