import React, { useRef, useMemo } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { Float, MeshDistortMaterial, Sphere, Torus, Environment, Stars, Box, Octahedron, MeshWobbleMaterial, Cylinder } from '@react-three/drei';
import * as THREE from 'three';

const MeshStandardMaterial = 'meshStandardMaterial' as any;
const AmbientLight = 'ambientLight' as any;
const PointLight = 'pointLight' as any;
const SpotLight = 'spotLight' as any;
const Group = 'group' as any;

const AuditNode = ({ position, color, scale = 1 }: { position: [number, number, number]; color: string; scale?: number }) => {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      ref.current.position.y = position[1] + Math.sin(t * 1.2 + position[0]) * 0.1;
      ref.current.rotation.y = t * 0.3;
    }
  });

  return (
    <Octahedron ref={ref} args={[1, 0]} position={position} scale={scale}>
      <MeshStandardMaterial
        color={color}
        envMapIntensity={1}
        metalness={0.9}
        roughness={0.1}
        emissive={color}
        emissiveIntensity={0.2}
      />
    </Octahedron>
  );
};

