      <Canvas camera={{ position: [0, 0, 8], fov: 45 }}>
        <AmbientLight intensity={1.5} />
        <PointLight position={[10, 10, 10]} intensity={2} />
        <Float speed={1.5} rotationIntensity={0.2} floatIntensity={0.4}>
          <AuditNode position={[0, 0, 0]} color="#002B5B" scale={1.2} />
          <Torus args={[3.5, 0.01, 16, 100]} rotation={[Math.PI / 2, 0, 0]}>
            <MeshStandardMaterial color="#E8D2A6" emissive="#E8D2A6" emissiveIntensity={0.5} />
          </Torus>
          <Torus args={[4, 0.005, 16, 100]} rotation={[0.5, 0.5, 0]}>
            <MeshStandardMaterial color="#E8D2A6" transparent opacity={0.3} />
          </Torus>
        </Float>
        <Stars radius={100} depth={50} count={2000} factor={4} saturation={0} fade speed={1.5} />
      </Canvas>
    </div>
  );
};

