import React, { useRef } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { Float, MeshDistortMaterial, Sphere, Torus, Environment, Stars, Box, Octahedron } from '@react-three/drei';
import * as THREE from 'three';

const BusinessNode = ({ position, color, scale = 1 }: { position: [number, number, number]; color: string; scale?: number }) => {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      ref.current.position.y = position[1] + Math.sin(t * 1.5 + position[0]) * 0.15;
      ref.current.rotation.x = t * 0.2;
      ref.current.rotation.z = t * 0.1;
    }
  });

  return (
    <Sphere ref={ref} args={[1, 16, 16]} position={position} scale={scale}>
      <MeshDistortMaterial
        color={color}
        envMapIntensity={0.8}
        clearcoat={0.5}
        clearcoatRoughness={0.1}
        metalness={0.8}
        roughness={0.2}
        distort={0.3}
        speed={1.5}
      />
    </Sphere>
  );
};

const ConnectivityRing = ({ color = "#E8D2A6" }) => {
  const ref = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (ref.current) {
       const t = state.clock.getElapsedTime();
       ref.current.rotation.x = Math.sin(t * 0.1) * 0.1;
       ref.current.rotation.y = t * 0.05;
    }
  });

  return (
    <Torus ref={ref} args={[3, 0.015, 8, 64]} rotation={[Math.PI / 2, 0, 0]}>
      <meshStandardMaterial color={color} emissive={color} emissiveIntensity={0.5} transparent opacity={0.6} />
    </Torus>
  );
}

const CursorInteractiveElement = () => {
  const ref = useRef<THREE.Mesh>(null);
  const { viewport, mouse } = useThree();

  useFrame(() => {
    if (ref.current) {
      const x = (mouse.x * viewport.width) / 2;
      const y = (mouse.y * viewport.height) / 2;
      ref.current.position.x = THREE.MathUtils.lerp(ref.current.position.x, x, 0.05);
      ref.current.position.y = THREE.MathUtils.lerp(ref.current.position.y, y, 0.05);
      ref.current.rotation.y += 0.01;
      ref.current.rotation.x = THREE.MathUtils.lerp(ref.current.rotation.x, mouse.y * 1, 0.1);
    }
  });

  return (
    <Octahedron ref={ref} args={[0.3, 0]}>
      <meshStandardMaterial 
        color="#E8D2A6" 
        emissive="#E8D2A6" 
        emissiveIntensity={0.8} 
        metalness={1} 
        roughness={0.1} 
      />
    </Octahedron>
  );
}

