import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageSquare, X, Send, Bot, Loader2, Calendar } from 'lucide-react';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

interface AIChatbotProps {
  onActionRequested?: () => void;
}

export const AIChatbot: React.FC<AIChatbotProps> = ({ onActionRequested }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<{ role: 'bot' | 'user'; text: string; hasAction?: boolean }[]>([
    { role: 'bot', text: 'Senior Financial Architect active. How can I refine your compliance strategy today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMessage }]);
    setIsTyping(true);

    try {
      // Correct: Use a new GoogleGenAI instance with process.env.API_KEY
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      // Correct: Use GenerateContentResponse type for typing
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: userMessage,
        config: {
          systemInstruction: `You are the Win-Win Senior Financial Architect. 
          Goal: Provide extremely concise, professional, and institutional responses.
          Tone: Serious, precise, and authoritative.
          Brevity: 15 words or fewer per response. 
          Topic: Singapore compliance (SFRS, IRAS, CPF), audit support, and BPO excellence.
          Action: If the user asks for more than a brief fact, direct them to "Connect with Us".`,
          temperature: 0.2,
        },
      });

      // Correct: Access the text property directly on response
      const botText = response.text || "I require clarification to provide a precise response.";
      setMessages(prev => [...prev, { role: 'bot', text: botText, hasAction: true }]);
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'bot', text: "Internal disruption. Please retry." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200]">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 20 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 20 }}
            className="absolute bottom-20 right-0 w-[300px] md:w-[350px] h-[400px] bg-white dark:bg-stone-900 rounded-[2rem] shadow-2xl border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            {/* Header */}
            <div className="p-4 bg-corporate-blue text-white flex justify-between items-center">
              <div className="flex items-center gap-3">
                <Bot size={16} />
                <h4 className="text-[10px] font-black uppercase tracking-[0.2em]">Institutional Bot</h4>
              </div>
              <motion.button 
                whileHover={{ rotate: 90 }}
                onClick={() => setIsOpen(false)} 
                className="p-1 hover:bg-white/10 rounded-full transition-colors"
              >
                <X size={14} />
              </motion.button>
            </div>

            {/* Chat Messages */}
            <div 
              ref={scrollRef}
              className="flex-1 overflow-y-auto p-4 space-y-4 bg-stone-50/50 dark:bg-stone-950/20"
            >
              {messages.map((m, i) => (
                <motion.div 
                  key={i}
                  initial={{ opacity: 0, x: m.role === 'user' ? 5 : -5 }}
                  animate={{ opacity: 1, x: 0 }}
                  className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}
                >
                  <div className={`max-w-[90%] p-3 rounded-2xl text-[11px] leading-snug font-medium ${
                    m.role === 'user' 
                      ? 'bg-corporate-gold text-white rounded-tr-none shadow-sm' 
                      : 'bg-white dark:bg-stone-800 text-stone-700 dark:text-stone-300 border dark:border-stone-700 rounded-tl-none'
                  }`}>
                    {m.text}
                  </div>
                  {m.role === 'bot' && m.hasAction && onActionRequested && i === messages.length - 1 && (
                    <motion.button
                      whileHover={{ scale: 1.05 }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => {
                        onActionRequested();
                        setIsOpen(false);
                      }}
                      className="mt-2 px-3 py-1.5 bg-corporate-blue text-white rounded-full text-[9px] font-black uppercase tracking-widest shadow-md"
                    >
                      Connect with Us
                    </motion.button>
                  )}
                </motion.div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-white dark:bg-stone-800 p-3 rounded-2xl rounded-tl-none border dark:border-stone-700">
                      <Loader2 size={12} className="animate-spin text-corporate-gold" />
                   </div>
                </div>
              )}
            </div>

            {/* Input */}
            <div className="p-3 bg-white dark:bg-stone-900 border-t dark:border-stone-800 flex gap-2">
              <input 
                type="text" 
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                placeholder="Message architect..."
                className="flex-1 bg-stone-100 dark:bg-stone-800 border-none rounded-full px-4 py-2 text-[11px] outline-none"
              />
              <motion.button 
                whileHover={{ scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={handleSend}
                disabled={isTyping}
                className="p-2 bg-corporate-blue text-white rounded-full disabled:opacity-50"
              >
                <Send size={12} />
              </motion.button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <motion.button
        whileHover={{ scale: 1.1 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(!isOpen)}
        className="w-14 h-14 bg-corporate-blue text-white rounded-full shadow-2xl flex items-center justify-center border-2 border-white/10"
      >
        {isOpen ? <X size={20} /> : <MessageSquare size={20} />}
      </motion.button>
    </div>
  );
};

