const InteractiveGlassSphere = () => {
  const meshRef = useRef<THREE.Mesh>(null);
  const { mouse, viewport } = useThree();

  useFrame((state) => {
    if (meshRef.current) {
      // Gentle follow mouse
      const targetX = (mouse.x * viewport.width) / 8;
      const targetY = (mouse.y * viewport.height) / 8;

      meshRef.current.position.x = THREE.MathUtils.lerp(meshRef.current.position.x, targetX, 0.02);
      meshRef.current.position.y = THREE.MathUtils.lerp(meshRef.current.position.y, targetY, 0.02);

      // Subtle float
      const t = state.clock.getElapsedTime();
      meshRef.current.position.y += Math.sin(t * 0.8) * 0.002;
      meshRef.current.rotation.z = t * 0.1;
    }
  });

  return (
    <Sphere ref={meshRef} args={[1.6, 64, 64]}>
      <MeshDistortMaterial
        color="#ffffff"
        speed={2}
        distort={0.2}
        radius={1}
        transparent
        opacity={0.3}
        metalness={0.1}
        roughness={0}
      />
      <FloatingCore />
    </Sphere>
  );
};

const ParticleField = () => {
  const count = 1500;
  const points = useMemo(() => {
    const p = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      p[i * 3] = (Math.random() - 0.5) * 20;
      p[i * 3 + 1] = (Math.random() - 0.5) * 20;
      p[i * 3 + 2] = (Math.random() - 0.5) * 20;
    }
    return p;
  }, []);

  const ref = useRef<THREE.Points>(null);
  const { mouse, viewport } = useThree();

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      ref.current.rotation.y = t * 0.02;
      // Drift towards mouse
      ref.current.position.x = THREE.MathUtils.lerp(ref.current.position.x, -mouse.x * 0.5, 0.05);
      ref.current.position.y = THREE.MathUtils.lerp(ref.current.position.y, -mouse.y * 0.5, 0.05);
    }
  });

  return (
    <Points ref={ref}>
      <BufferGeometry>
        <BufferAttribute
          attach="attributes-position"
          count={points.length / 3}
          array={points}
          itemSize={3}
        />
      </BufferGeometry>
      <PointsMaterial
        size={0.015}
        color="#D4B483"
        sizeAttenuation={true}
        transparent
        opacity={0.4}
      />
