const InteractiveGlassSphere = () => {
  const meshRef = useRef<THREE.Mesh>(null);
  const groupRef = useRef<THREE.Group>(null);
  const { mouse, viewport } = useThree();

  useFrame((state) => {
    if (meshRef.current && groupRef.current) {
      // Gentle follow mouse with lag for smoothness
      const targetX = (mouse.x * viewport.width) / 10;
      const targetY = (mouse.y * viewport.height) / 10;

      groupRef.current.position.x = THREE.MathUtils.lerp(groupRef.current.position.x, targetX, 0.03);
      groupRef.current.position.y = THREE.MathUtils.lerp(groupRef.current.position.y, targetY, 0.03);

      // Interactive Tilt based on mouse
      groupRef.current.rotation.x = THREE.MathUtils.lerp(groupRef.current.rotation.x, -mouse.y * 0.4, 0.05);
      groupRef.current.rotation.y = THREE.MathUtils.lerp(groupRef.current.rotation.y, mouse.x * 0.4, 0.05);

      const t = state.clock.getElapsedTime();
      meshRef.current.rotation.z = t * 0.05;
    }
  });

  return (
    <Group ref={groupRef}>
      <Sphere ref={meshRef} args={[1.6, 64, 64]}>
        <MeshDistortMaterial
          color="#ffffff"
          speed={1.5}
          distort={0.15}
          radius={1}
          transparent
          opacity={0.25}
          metalness={0.2}
          roughness={0}
        />
        <FloatingCore />
      </Sphere>
    </Group>
  );
};

const OrbitalNode = ({ index }: { index: number }) => {
  const ref = useRef<THREE.Group>(null);
  const { mouse } = useThree();
  const randomOffset = useMemo(() => Math.random() * Math.PI * 2, []);
  const radius = useMemo(() => 2.5 + Math.random() * 1.5, []);

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      const angle = t * 0.2 + randomOffset;
      // Base orbit
      const baseX = Math.cos(angle) * radius;
      const baseZ = Math.sin(angle) * radius;
      const baseY = Math.sin(angle * 0.5) * 1.5;

      // Mouse influence (slight nudge)
      const mouseX = mouse.x * 0.5;
      const mouseY = mouse.y * 0.5;

      ref.current.position.x = THREE.MathUtils.lerp(ref.current.position.x, baseX + mouseX, 0.05);
      ref.current.position.y = THREE.MathUtils.lerp(ref.current.position.y, baseY + mouseY, 0.05);
      ref.current.position.z = baseZ;

      ref.current.rotation.y += 0.01;
    }
  });

  return (
    <Group ref={ref}>
      <Octahedron args={[0.08, 0]}>
        <MeshStandardMaterial color="#D4B483" emissive="#D4B483" emissiveIntensity={1} />
      </Octahedron>
    </Group>
  );
};

const RefinedParticleField = ({ count = 2000, color = "#D4B483", parallaxFactor = 1 }) => {
  const points = useMemo(() => {
    const p = new Float32Array(count * 3);
    for (let i = 0; i < count; i++) {
      p[i * 3] = (Math.random() - 0.5) * 30;
      p[i * 3 + 1] = (Math.random() - 0.5) * 30;
      p[i * 3 + 2] = (Math.random() - 0.5) * 20 - 5;
    }
    return p;
  }, [count]);

  const ref = useRef<THREE.Points>(null);
  const { mouse } = useThree();

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      ref.current.rotation.y = t * 0.01;
      // Parallax effect
      const targetX = -mouse.x * 1.2 * parallaxFactor;
      const targetY = -mouse.y * 1.2 * parallaxFactor;
      ref.current.position.x = THREE.MathUtils.lerp(ref.current.position.x, targetX, 0.02);
      ref.current.position.y = THREE.MathUtils.lerp(ref.current.position.y, targetY, 0.02);
    }
  });

  return (
    <Points ref={ref}>
      <BufferGeometry>
        <BufferAttribute
          attach="attributes-position"
          count={points.length / 3}
          array={points}
          itemSize={3}
        />
      </BufferGeometry>
      <PointsMaterial
        size={0.02}
        color={color}
        sizeAttenuation={true}
        transparent
        opacity={0.3}
        blending={THREE.AdditiveBlending}
      />
    </Points>
  );
};

