import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageSquare, X, Send, Bot, Loader2, MapPin, Globe, ExternalLink, Search } from 'lucide-react';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

interface GroundingLink {
  uri: string;
  title: string;
}

interface Message {
  role: 'bot' | 'user';
  text: string;
  hasAction?: boolean;
  links?: GroundingLink[];
  modelUsed?: string;
}

interface AIChatbotProps {
  onActionRequested?: () => void;
}

export const AIChatbot: React.FC<AIChatbotProps> = ({ onActionRequested }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'bot', text: 'Senior Financial Architect active. How can I refine your compliance strategy today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const getPosition = (): Promise<GeolocationPosition | null> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) return resolve(null);
      navigator.geolocation.getCurrentPosition(
        (pos) => resolve(pos),
        () => resolve(null),
        { timeout: 5000 }
      );
    });
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input.trim().toLowerCase();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: input.trim() }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let model = 'gemini-2.5-flash-lite'; // Default low-latency model
      let tools: any[] | undefined = undefined;
      let toolConfig: any = undefined;

      // Intent detection for Grounding
      const isLocationQuery = userMessage.match(/near|where|map|location|address|restaurant|office|singapore/);
      const isSearchQuery = userMessage.match(/news|current|latest|today|weather|recent|update|market|trend/);
      const isComplexQuery = userMessage.length > 100 || userMessage.match(/analyze|compare|detailed|explain|strategy|calculate/);

      if (isLocationQuery) {
        model = 'gemini-2.5-flash';
        tools = [{ googleMaps: {} }];
        const pos = await getPosition();
        if (pos) {
          toolConfig = {
            retrievalConfig: {
              latLng: {
                latitude: pos.coords.latitude,
                longitude: pos.coords.longitude
              }
            }
          };
        }
      } else if (isSearchQuery) {
        model = 'gemini-3-flash-preview';
        tools = [{ googleSearch: {} }];
      } else if (isComplexQuery) {
        model = 'gemini-3-pro-preview';
      }

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: input.trim(),
        config: {
          systemInstruction: `You are the Win-Win Senior Financial Architect. 
          Goal: Provide extremely concise, professional, and institutional responses.
          Tone: Serious, precise, and authoritative.
          Brevity: Maximum 30 words per response. 
          Context: Singapore compliance (SFRS, IRAS, CPF), audit support, and BPO excellence.
          Action: If the user asks for more than a brief fact, direct them to "Connect with Us".`,
          temperature: 0.1,
          tools,
          toolConfig
        },
      });

      const botText = response.text || "I require clarification to provide a precise response.";

      // Extract Grounding Links
      const links: GroundingLink[] = [];
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        chunks.forEach((chunk: any) => {
          if (chunk.web?.uri) {
            links.push({ uri: chunk.web.uri, title: chunk.web.title || 'Source' });
          } else if (chunk.maps?.uri) {
            links.push({ uri: chunk.maps.uri, title: chunk.maps.title || 'Location' });
          }
        });
      }

      setMessages(prev => [...prev, { 
        role: 'bot', 
        text: botText, 
        hasAction: true, 
        links: links.length > 0 ? links : undefined,
        modelUsed: model.replace('gemini-', '')
      }]);
    } catch (error) {
      console.error("AI Error:", error);
      setMessages(prev => [...prev, { role: 'bot', text: "Service temporary disruption. Direct inquiry recommended." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200]">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.8, y: 50, filter: 'blur(10px)' }}
            animate={{ opacity: 1, scale: 1, y: 0, filter: 'blur(0px)' }}
            exit={{ opacity: 0, scale: 0.8, y: 50, filter: 'blur(10px)' }}
            className="absolute bottom-20 right-0 w-[320px] md:w-[380px] h-[500px] bg-white dark:bg-stone-900 rounded-[2.5rem] shadow-2xl border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            {/* Header */}
            <div className="p-5 bg-corporate-blue text-white flex justify-between items-center relative overflow-hidden">
              <div className="absolute inset-0 bg-corporate-gold/10 opacity-20 pointer-events-none" />
              <div className="flex items-center gap-3 relative z-10">
                <motion.div 
                  animate={{ rotate: [0, 10, -10, 0] }}
                  transition={{ repeat: Infinity, duration: 4 }}
                  className="p-1.5 bg-corporate-gold rounded-lg shadow-lg"
                >
                  <Bot size={18} />
                </motion.div>
                <div>
                  <h4 className="text-[11px] font-black uppercase tracking-[0.25em]">Win-Win Architect</h4>
                  <div className="flex items-center gap-1.5">
                    <div className="w-1.5 h-1.5 rounded-full bg-green-400 animate-pulse" />
                    <span className="text-[8px] font-bold uppercase tracking-widest opacity-60">Neural Node Active</span>
                  </div>
                </div>
              </div>
              <motion.button 
                whileHover={{ rotate: 90, scale: 1.1 }}
                whileTap={{ scale: 0.9 }}
                onClick={() => setIsOpen(false)} 
                className="p-2 hover:bg-white/10 rounded-full transition-colors"
              >
                <X size={16} />
              </motion.button>
            </div>

            {/* Chat Messages */}
            <div 
              ref={scrollRef}
              className="flex-1 overflow-y-auto p-5 space-y-6 bg-stone-50/30 dark:bg-stone-950/20 scroll-smooth"
            >
              {messages.map((m, i) => (
                <motion.div 
                  key={i}
                  initial={{ opacity: 0, x: m.role === 'user' ? 20 : -20, scale: 0.95 }}
                  animate={{ opacity: 1, x: 0, scale: 1 }}
                  className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}
                >
                  <div className={`max-w-[85%] p-4 rounded-2xl text-[12px] leading-relaxed font-medium shadow-sm transition-all duration-300 ${
                    m.role === 'user' 
                      ? 'bg-corporate-gold text-white rounded-tr-none' 
                      : 'bg-white dark:bg-stone-800 text-stone-800 dark:text-stone-200 border border-stone-100 dark:border-stone-700 rounded-tl-none'
                  }`}>
                    {m.text}
                    {m.modelUsed && (
                      <div className="mt-2 pt-2 border-t border-stone-100/50 dark:border-stone-700/50 flex items-center justify-between">
                        <span className="text-[7px] font-black uppercase tracking-widest opacity-40">Engined by {m.modelUsed}</span>
                        {m.modelUsed.includes('flash') && <Zap size={8} className="text-corporate-gold opacity-50" />}
                      </div>
                    )}
                  </div>

                  {m.links && m.links.length > 0 && (
                    <div className="mt-3 flex flex-wrap gap-2 max-w-[85%]">
                      {m.links.map((link, idx) => (
                        <motion.a
                          key={idx}
                          href={link.uri}
                          target="_blank"
                          rel="noopener noreferrer"
                          whileHover={{ scale: 1.05, y: -2 }}
                          className="px-3 py-1.5 bg-stone-100 dark:bg-stone-800 rounded-lg border border-stone-200 dark:border-stone-700 flex items-center gap-2 text-[9px] font-bold text-corporate-blue dark:text-corporate-gold"
                        >
                          {link.uri.includes('google.com/maps') ? <MapPin size={10} /> : <Globe size={10} />}
                          <span className="truncate max-w-[120px]">{link.title}</span>
                          <ExternalLink size={8} />
                        </motion.a>
                      ))}
                    </div>
                  )}

                  {m.role === 'bot' && m.hasAction && onActionRequested && i === messages.length - 1 && (
                    <motion.button
                      whileHover={{ scale: 1.05, y: -2, boxShadow: '0 10px 15px -3px rgba(0, 43, 91, 0.2)' }}
                      whileTap={{ scale: 0.95 }}
                      onClick={() => {
                        onActionRequested();
                        setIsOpen(false);
                      }}
                      className="mt-3 px-5 py-2 bg-corporate-blue text-white rounded-xl text-[9px] font-black uppercase tracking-[0.2em] shadow-lg flex items-center gap-2"
                    >
                      Institutional Inquiry <Search size={12} />
                    </motion.button>
                  )}
                </motion.div>
              ))}
              {isTyping && (
                <motion.div 
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  className="flex justify-start"
                >
                   <div className="bg-white dark:bg-stone-800 p-4 rounded-2xl rounded-tl-none border border-stone-100 dark:border-stone-700 shadow-sm flex items-center gap-2">
                      <Loader2 size={14} className="animate-spin text-corporate-gold" />
                      <span className="text-[10px] font-black uppercase tracking-widest opacity-50">Thinking...</span>
                   </div>
                </motion.div>
              )}
            </div>

            {/* Input Area */}
            <div className="p-4 bg-white dark:bg-stone-900 border-t dark:border-stone-800">
              <div className="flex gap-2 p-1.5 bg-stone-100 dark:bg-stone-800 rounded-[1.5rem] shadow-inner focus-within:ring-2 focus-within:ring-corporate-gold/50 transition-all">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Inquire compliance specifics..."
                  className="flex-1 bg-transparent border-none rounded-full px-4 py-2 text-[12px] outline-none font-medium placeholder:opacity-40"
                />
                <motion.button 
                  whileHover={{ scale: 1.1, rotate: 15 }}
                  whileTap={{ scale: 0.9 }}
                  onClick={handleSend}
                  disabled={isTyping || !input.trim()}
                  className="p-2.5 bg-corporate-blue text-white rounded-full disabled:opacity-30 disabled:grayscale transition-all shadow-md"
                >
                  <Send size={14} />
                </motion.button>
              </div>
              <div className="mt-3 flex justify-center gap-4 opacity-30">
                <div className="flex items-center gap-1">
                  <Globe size={8} /> <span className="text-[7px] font-black uppercase">Search Grounding</span>
                </div>
                <div className="flex items-center gap-1">
                  <MapPin size={8} /> <span className="text-[7px] font-black uppercase">Maps Enabled</span>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      {/* Trigger Button */}
      <motion.button
        whileHover={{ scale: 1.1, y: -5, boxShadow: '0 25px 50px -12px rgba(0, 43, 91, 0.4)' }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(!isOpen)}
        className={`relative w-16 h-16 bg-corporate-blue text-white rounded-full shadow-2xl flex items-center justify-center border-2 border-white/20 transition-colors duration-500 ${isOpen ? 'bg-corporate-gold' : ''}`}
      >
        <AnimatePresence>
          {!isOpen && (
            <motion.div
              initial={{ opacity: 0, scale: 0.5 }}
              animate={{ opacity: 1, scale: 1 }}
              exit={{ opacity: 0, scale: 0.5 }}
              className="absolute -top-1 -right-1 w-5 h-5 bg-corporate-gold rounded-full flex items-center justify-center shadow-lg z-10"
            >
              <motion.div 
                animate={{ scale: [1, 1.4, 1], opacity: [1, 0.5, 1] }}
                transition={{ repeat: Infinity, duration: 2.5 }}
                className="w-2.5 h-2.5 bg-white rounded-full"
              />
            </motion.div>
          )}
        </AnimatePresence>
        {isOpen ? <X size={24} /> : <MessageSquare size={24} />}
      </motion.button>
    </div>
  );
};

