import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageSquare, X, Send, Bot, Loader2, MapPin, Globe, ExternalLink, Search, Zap } from 'lucide-react';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

interface GroundingLink {
  uri: string;
  title: string;
}

interface Message {
  role: 'bot' | 'user';
  text: string;
  hasAction?: boolean;
  links?: GroundingLink[];
  modelUsed?: string;
}

interface AIChatbotProps {
  onActionRequested?: () => void;
}

export const AIChatbot: React.FC<AIChatbotProps> = ({ onActionRequested }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'bot', text: 'Senior Financial Architect active. How can I refine your compliance strategy today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const getPosition = (): Promise<GeolocationPosition | null> => {
    return new Promise((resolve) => {
      if (!navigator.geolocation) return resolve(null);
      navigator.geolocation.getCurrentPosition(
        (pos) => resolve(pos),
        () => resolve(null),
        { timeout: 5000 }
      );
    });
  };

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;

    const userMessage = input.trim().toLowerCase();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: input.trim() }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      let model = 'gemini-2.5-flash-lite';
      let tools: any[] | undefined = undefined;
      let toolConfig: any = undefined;

      const isLocationQuery = userMessage.match(/near|where|map|location|address|office|singapore/);
      const isSearchQuery = userMessage.match(/news|current|latest|today|weather|recent|update/);
      const isComplexQuery = userMessage.length > 100 || userMessage.match(/analyze|compare|detailed|explain/);

      if (isLocationQuery) {
        model = 'gemini-2.5-flash';
        tools = [{ googleMaps: {} }];
        const pos = await getPosition();
        if (pos) {
          toolConfig = {
            retrievalConfig: {
              latLng: {
                latitude: pos.coords.latitude,
                longitude: pos.coords.longitude
              }
            }
          };
        }
      } else if (isSearchQuery) {
        model = 'gemini-3-flash-preview';
        tools = [{ googleSearch: {} }];
      } else if (isComplexQuery) {
        model = 'gemini-3-pro-preview';
      }

      const response: GenerateContentResponse = await ai.models.generateContent({
        model,
        contents: input.trim(),
        config: {
          systemInstruction: `You are the Win-Win Senior Financial Architect. Concise (max 30 words), professional, authoritative. Focus: Singapore compliance.`,
          temperature: 0.1,
          tools,
          toolConfig
        },
      });

      const botText = response.text || "I require clarification.";
      const links: GroundingLink[] = [];
      const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
      if (chunks) {
        chunks.forEach((chunk: any) => {
          if (chunk.web?.uri) links.push({ uri: chunk.web.uri, title: chunk.web.title || 'Source' });
          else if (chunk.maps?.uri) links.push({ uri: chunk.maps.uri, title: chunk.maps.title || 'Location' });
        });
      }

      setMessages(prev => [...prev, { 
        role: 'bot', 
        text: botText, 
        hasAction: true, 
        links: links.length > 0 ? links : undefined,
        modelUsed: model.replace('gemini-', '')
      }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: "Service temporary disruption." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200]">
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, scale: 0.9, y: 50, filter: 'blur(10px)' }}
            animate={{ opacity: 1, scale: 1, y: 0, filter: 'blur(0px)' }}
            exit={{ opacity: 0, scale: 0.9, y: 50, filter: 'blur(10px)' }}
            // Responsive width: 90vw on small screens, fixed max width on larger
            className="absolute bottom-20 right-0 w-[calc(100vw-3rem)] md:w-[380px] h-[75vh] md:h-[500px] bg-white dark:bg-stone-900 rounded-[2rem] shadow-2xl border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden"
          >
            {/* Header */}
            <div className="p-4 md:p-5 bg-corporate-blue text-white flex justify-between items-center relative overflow-hidden">
              <div className="flex items-center gap-3 relative z-10">
                <div className="p-1.5 bg-corporate-gold rounded-lg shadow-lg"><Bot size={16} /></div>
                <div>
                  <h4 className="text-[10px] font-black uppercase tracking-[0.2em]">Win-Win Architect</h4>
                  <div className="flex items-center gap-1">
                    <div className="w-1 h-1 rounded-full bg-green-400 animate-pulse" />
                    <span className="text-[7px] font-bold uppercase tracking-widest opacity-60">Active</span>
                  </div>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)} className="p-1 hover:bg-white/10 rounded-full transition-colors"><X size={16} /></button>
            </div>

            {/* Chat Messages */}
            <div ref={scrollRef} className="flex-1 overflow-y-auto p-4 md:p-5 space-y-4 md:space-y-6 bg-stone-50/30 dark:bg-stone-950/20 scroll-smooth">
              {messages.map((m, i) => (
                <div key={i} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[85%] p-3 md:p-4 rounded-2xl text-[11px] md:text-[12px] leading-relaxed font-medium shadow-sm transition-all duration-300 ${
                    m.role === 'user' 
                      ? 'bg-corporate-gold text-white rounded-tr-none' 
                      : 'bg-white dark:bg-stone-800 text-stone-800 dark:text-stone-200 border border-stone-100 dark:border-stone-700 rounded-tl-none'
                  }`}>
                    {m.text}
                  </div>
                  {m.links && (
                    <div className="mt-2 flex flex-wrap gap-2 max-w-[85%]">
                      {m.links.map((link, idx) => (
                        <a key={idx} href={link.uri} target="_blank" rel="noopener noreferrer" className="px-2 py-1 bg-stone-100 dark:bg-stone-800 rounded-lg border border-stone-200 dark:border-stone-700 flex items-center gap-1.5 text-[9px] font-bold text-corporate-blue dark:text-corporate-gold">
                          <span className="truncate max-w-[80px]">{link.title}</span>
                          <ExternalLink size={8} />
                        </a>
                      ))}
                    </div>
                  )}
                  {m.role === 'bot' && m.hasAction && onActionRequested && i === messages.length - 1 && (
                    <button onClick={() => { onActionRequested(); setIsOpen(false); }} className="mt-2 px-4 py-2 bg-corporate-blue text-white rounded-lg text-[9px] font-black uppercase tracking-widest shadow-md">
                      Connect with Us
                    </button>
                  )}
                </div>
              ))}
              {isTyping && (
                <div className="flex justify-start">
                   <div className="bg-white dark:bg-stone-800 p-3 rounded-2xl rounded-tl-none border border-stone-100 dark:border-stone-700 flex items-center gap-2">
                      <Loader2 size={12} className="animate-spin text-corporate-gold" />
                      <span className="text-[9px] font-black uppercase tracking-widest opacity-40">Architect Thinking...</span>
                   </div>
                </div>
              )}
            </div>

            {/* Input Area */}
            <div className="p-4 bg-white dark:bg-stone-900 border-t dark:border-stone-800">
              <div className="flex gap-2 p-1.5 bg-stone-100 dark:bg-stone-800 rounded-2xl shadow-inner">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Inquire..."
                  className="flex-1 bg-transparent border-none px-3 py-1.5 text-[12px] outline-none"
                />
                <motion.button whileTap={{ scale: 0.9 }} onClick={handleSend} disabled={isTyping || !input.trim()} className="p-2 bg-corporate-blue text-white rounded-full disabled:opacity-30 transition-all shadow-md">
                  <Send size={14} />
                </motion.button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <motion.button
        whileHover={{ y: -5 }}
        whileTap={{ scale: 0.9 }}
        onClick={() => setIsOpen(!isOpen)}
        className={`relative w-14 h-14 md:w-16 md:h-16 bg-corporate-blue text-white rounded-full shadow-2xl flex items-center justify-center border-2 border-white/20 transition-all duration-500 ${isOpen ? 'bg-corporate-gold' : ''}`}
      >
        <AnimatePresence>
          {!isOpen && (
            <motion.div initial={{ opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.5 }} className="absolute -top-1 -right-1 w-4 h-4 bg-corporate-gold rounded-full flex items-center justify-center shadow-lg">
              <div className="w-1.5 h-1.5 bg-white rounded-full animate-pulse" />
            </motion.div>
          )}
        </AnimatePresence>
        {isOpen ? <X size={20} /> : <MessageSquare size={20} />}
      </motion.button>
    </div>
  );
};

