  const lenisRef = useRef<Lenis | null>(null);

  const [formState, setFormState] = useState<'idle' | 'submitting' | 'success'>('idle');

  useEffect(() => {
    // Initialize Lenis for buttery-smooth inertial scrolling
    const lenis = new Lenis({
      duration: 1.2,
      easing: (t) => Math.min(1, 1.001 - Math.pow(2, -10 * t)),
      orientation: 'vertical',
      gestureOrientation: 'vertical',
      smoothWheel: true,
      wheelMultiplier: 1,
      touchMultiplier: 2,
      infinite: false,
    });

    lenisRef.current = lenis;

    function raf(time: number) {
      lenis.raf(time);
      requestAnimationFrame(raf);
    }

    requestAnimationFrame(raf);

    const handleScroll = () => {
      const scrollPos = window.scrollY;
      const shouldBeScrolled = scrollPos > 50;
      const shouldShowBackToTop = scrollPos > 400;
      setScrolled(prev => prev !== shouldBeScrolled ? shouldBeScrolled : prev);
      setShowBackToTop(prev => prev !== shouldShowBackToTop ? shouldShowBackToTop : prev);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });

    return () => {
      window.removeEventListener('scroll', handleScroll);
      lenis.destroy();
    };
  }, []);

  const navigateTo = useCallback((page: Page) => {
    setCurrentPage(page);
