import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MessageSquare, X, Send, Bot, Loader2, MapPin, Globe, ExternalLink, Search, Zap } from 'lucide-react';
import { GoogleGenAI, GenerateContentResponse } from "@google/genai";

// FONT CONSTANTS
const FONT_BODY = "font-serif italic";
const FONT_ACCENT = "font-sans font-black uppercase tracking-[0.2em]";

interface Message {
  role: 'bot' | 'user';
  text: string;
}

interface AIChatbotProps {
  onActionRequested?: () => void;
}

export const AIChatbot: React.FC<AIChatbotProps> = ({ onActionRequested }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<Message[]>([
    { role: 'bot', text: 'Senior Financial Architect active. How can I refine your compliance strategy today?' }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping]);

  const handleSend = async () => {
    if (!input.trim() || isTyping) return;
    const currentInput = input.trim();
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: currentInput }]);
    setIsTyping(true);

    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: currentInput,
        config: {
          systemInstruction: `You are the Win-Win Senior Financial Architect. Concise (max 30 words), professional, authoritative. Focus: Singapore compliance. Use a sophisticated tone.`,
          temperature: 0.1,
        },
      });

      setMessages(prev => [...prev, { role: 'bot', text: response.text || "Clarification required." }]);
    } catch (error) {
      setMessages(prev => [...prev, { role: 'bot', text: "Service temporarily disrupted." }]);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="fixed bottom-6 right-6 z-[200]">
      <AnimatePresence>
        {isOpen && (
          <motion.div initial={{ opacity: 0, scale: 0.9, y: 40 }} animate={{ opacity: 1, scale: 1, y: 0 }} exit={{ opacity: 0, scale: 0.9, y: 40 }} className="absolute bottom-24 right-0 w-[calc(100vw-3rem)] md:w-[380px] h-[550px] bg-white dark:bg-stone-900 rounded-[2.5rem] shadow-2xl border border-stone-200 dark:border-stone-800 flex flex-col overflow-hidden">
            <div className="p-6 bg-corporate-blue text-white flex justify-between items-center">
              <div className="flex items-center gap-4">
                <div className="p-2 bg-corporate-gold rounded-xl"><Bot size={18} /></div>
                <div>
                  <h4 className={`${FONT_ACCENT} text-[10px]`}>Win-Win Architect</h4>
                  <span className={`${FONT_BODY} text-xs opacity-60`}>Institutional Intelligence</span>
                </div>
              </div>
              <button onClick={() => setIsOpen(false)}><X size={20} /></button>
            </div>

            <div ref={scrollRef} className="flex-1 overflow-y-auto p-6 space-y-8 bg-stone-50/30 dark:bg-stone-950/20">
              {messages.map((m, i) => (
                <div key={i} className={`flex flex-col ${m.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[85%] p-5 rounded-2xl ${FONT_BODY} text-lg leading-relaxed shadow-sm ${
                    m.role === 'user' ? 'bg-corporate-gold text-white rounded-tr-none' : 'bg-white dark:bg-stone-800 text-stone-800 dark:text-stone-200 border border-stone-100 dark:border-stone-700 rounded-tl-none'
                  }`}>
                    {m.text}
                  </div>
                </div>
              ))}
              {isTyping && (
                <div className={`${FONT_ACCENT} text-[10px] opacity-40 flex items-center gap-2`}>
                  <Loader2 size={12} className="animate-spin" /> Thinking...
                </div>
              )}
            </div>

            <div className="p-6 bg-white dark:bg-stone-900 border-t dark:border-stone-800">
              <div className="flex gap-4 p-2 bg-stone-100 dark:bg-stone-800 rounded-2xl">
                <input 
                  type="text" 
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                  placeholder="Inquire..."
                  className={`${FONT_BODY} text-lg flex-1 bg-transparent border-none px-4 py-2 outline-none`}
                />
                <button onClick={handleSend} className="p-3 bg-corporate-blue text-white rounded-xl"><Send size={16} /></button>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>

      <button onClick={() => setIsOpen(!isOpen)} className={`relative w-16 h-16 bg-corporate-blue text-white rounded-full shadow-2xl flex items-center justify-center transition-all ${isOpen ? 'bg-corporate-gold rotate-90' : ''}`}>
        {isOpen ? <X size={22} /> : <MessageSquare size={22} />}
      </button>
    </div>
  );
};

