const staggerVariants: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1, transition: { staggerChildren: 0.1 } }
};

const calcTilt = (x: number, y: number, rect: DOMRect) => [
  -(y - rect.top - rect.height / 2) / 15,
  (x - rect.left - rect.width / 2) / 15,
  1.02
];

const transTilt = (x: number, y: number, s: number) =>
  `perspective(800px) rotateX(${x}deg) rotateY(${y}deg) scale(${s})`;

const ServiceCard = ({ service, onClick }: { service: RichDetail, onClick: (s: RichDetail) => void }) => {
  const [props, set] = useSpring(() => ({
    xys: [0, 0, 1],
    config: config.gentle
  }));

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    set.start({ xys: calcTilt(e.clientX, e.clientY, rect) });
  };

  const handleMouseLeave = () => set.start({ xys: [0, 0, 1] });

  return (
    <animated.div
      style={{ transform: props.xys.to(transTilt) }}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className="p-12 bg-white dark:bg-stone-900 border border-stone-100 dark:border-stone-800 rounded-[3rem] shadow-sm hover:shadow-2xl transition-shadow group overflow-hidden relative text-left cursor-pointer"
      onClick={() => onClick(service)}
