import React, { useRef, useMemo } from 'react';
import { Canvas, useFrame, useThree } from '@react-three/fiber';
import { Float, MeshDistortMaterial, Sphere, Torus, Environment, Stars, Box, Octahedron, MeshWobbleMaterial } from '@react-three/drei';
import * as THREE from 'three';

// Fixes for JSX.IntrinsicElements errors in the current environment
// @ts-ignore
const MeshStandardMaterial = 'meshStandardMaterial' as any;
// @ts-ignore
const AmbientLight = 'ambientLight' as any;
// @ts-ignore
const PointLight = 'pointLight' as any;
// @ts-ignore
const SpotLight = 'spotLight' as any;
// @ts-ignore
const Group = 'group' as any;
// @ts-ignore
const Points = 'points' as any;
// @ts-ignore
const BufferGeometry = 'bufferGeometry' as any;
// @ts-ignore
const BufferAttribute = 'bufferAttribute' as any;
// @ts-ignore
const PointsMaterial = 'pointsMaterial' as any;

const StarFieldGalaxy = () => {
  const pointsRef = useRef<THREE.Points>(null);
  const { mouse } = useThree();

  const [particles, sizes, shift] = useMemo(() => {
    const pCount = 20000;
    const ringCount = 30000;
    const total = pCount + ringCount;

    const positions = new Float32Array(total * 3);
    const s = new Float32Array(total);
    const sh = new Float32Array(total * 4);

    for (let i = 0; i < pCount; i++) {
      const vec = new THREE.Vector3().randomDirection().multiplyScalar(Math.random() * 0.5 + 9.5);
      positions[i * 3] = vec.x;
      positions[i * 3 + 1] = vec.y;
      positions[i * 3 + 2] = vec.z;
      s[i] = Math.random() * 1.5 + 0.5;
      sh[i * 4] = Math.random() * Math.PI;
      sh[i * 4 + 1] = Math.random() * Math.PI * 2;
      sh[i * 4 + 2] = (Math.random() * 0.9 + 0.1) * Math.PI * 0.1;
      sh[i * 4 + 3] = Math.random() * 0.9 + 0.1;
    }

    for (let i = pCount; i < total; i++) {
      const r = 10, R = 40;
      const rand = Math.pow(Math.random(), 1.5);
      const radius = Math.sqrt(R * R * rand + (1 - rand) * r * r);
      const angle = Math.random() * 2 * Math.PI;
      const height = (Math.random() - 0.5) * 4;

      positions[i * 3] = Math.cos(angle) * radius;
      positions[i * 3 + 1] = height;
      positions[i * 3 + 2] = Math.sin(angle) * radius;

      s[i] = Math.random() * 1.5 + 0.5;
      sh[i * 4] = Math.random() * Math.PI;
      sh[i * 4 + 1] = Math.random() * Math.PI * 2;
      sh[i * 4 + 2] = (Math.random() * 0.9 + 0.1) * Math.PI * 0.1;
      sh[i * 4 + 3] = Math.random() * 0.9 + 0.1;
    }

    return [positions, s, sh];
  }, []);

  const uniforms = useMemo(() => ({
    time: { value: 0 }
  }), []);

  useFrame((state) => {
    if (pointsRef.current) {
      uniforms.time.value = state.clock.getElapsedTime() * 0.5 * Math.PI;
      pointsRef.current.rotation.y = state.clock.getElapsedTime() * 0.05;

      // Slight parallax based on mouse
      const targetX = mouse.x * 2;
      const targetY = mouse.y * 2;
      pointsRef.current.position.x = THREE.MathUtils.lerp(pointsRef.current.position.x, targetX, 0.01);
      pointsRef.current.position.y = THREE.MathUtils.lerp(pointsRef.current.position.y, targetY, 0.01);
    }
  });

  return (
    <Points ref={pointsRef} rotation={[0.2, 0, 0]}>
      <BufferGeometry>
        <BufferAttribute attach="attributes-position" count={particles.length / 3} array={particles} itemSize={3} />
        <BufferAttribute attach="attributes-sizes" count={sizes.length} array={sizes} itemSize={1} />
        <BufferAttribute attach="attributes-shift" count={shift.length / 4} array={shift} itemSize={4} />
      </BufferGeometry>
      <PointsMaterial
        size={0.125}
        transparent
        depthTest={false}
        blending={THREE.AdditiveBlending}
        onBeforeCompile={(shader: any) => {
          shader.uniforms.time = uniforms.time;
          shader.vertexShader = `
            uniform float time;
            attribute float sizes;
            attribute vec4 shift;
            varying vec3 vColor;
            ${shader.vertexShader}
          `.replace(
            `gl_PointSize = size;`,
            `gl_PointSize = size * sizes;`
          ).replace(
            `#include <color_vertex>`,
            `#include <color_vertex>
              float d = length(abs(position) / vec3(40., 10., 40));
              d = clamp(d, 0., 1.);
              vColor = mix(vec3(212., 180., 131.), vec3(0., 43., 91.), d) / 255.;
            `
          ).replace(
            `#include <begin_vertex>`,
            `#include <begin_vertex>
              float t = time;
              float moveT = mod(shift.x + shift.z * t, 6.28318);
              float moveS = mod(shift.y + shift.z * t, 6.28318);
              transformed += vec3(cos(moveS) * sin(moveT), cos(moveT), sin(moveS) * sin(moveT)) * shift.w;
            `
          );
          shader.fragmentShader = `
            varying vec3 vColor;
            ${shader.fragmentShader}
          `.replace(
            `#include <clipping_planes_fragment>`,
            `#include <clipping_planes_fragment>
              float d = length(gl_PointCoord.xy - 0.5);
            `
          ).replace(
            `vec4 diffuseColor = vec4( diffuse, opacity );`,
            `vec4 diffuseColor = vec4( vColor, smoothstep(0.5, 0.1, d) );`
          );
        }}
      />
    </Points>
  );
};

const FloatingCore = () => {
  const ref = useRef<THREE.Group>(null);

  useFrame((state) => {
    if (ref.current) {
      const t = state.clock.getElapsedTime();
      ref.current.rotation.y = t * 0.4;
      ref.current.rotation.x = Math.sin(t * 0.5) * 0.3;
      ref.current.scale.setScalar(1 + Math.sin(t * 2) * 0.05);
    }
  });

  return (
    <Group ref={ref}>
      <Sphere args={[0.4, 32, 32]}>
        <MeshStandardMaterial 
          color="#D4B483" 
          emissive="#D4B483" 
          emissiveIntensity={2}
          metalness={1}
          roughness={0.1}
        />
      </Sphere>
      <Torus args={[0.8, 0.015, 16, 100]} rotation={[Math.PI / 2, 0, 0]}>
        <MeshStandardMaterial color="#D4B483" metalness={1} roughness={0} />
      </Torus>
    </Group>
  );
};

const InteractiveGlassSphere = () => {
  const meshRef = useRef<THREE.Mesh>(null);
  const groupRef = useRef<THREE.Group>(null);
  const { mouse, viewport } = useThree();

  useFrame((state) => {
    if (meshRef.current && groupRef.current) {
      const targetX = (mouse.x * viewport.width) / 10;
      const targetY = (mouse.y * viewport.height) / 10;
      groupRef.current.position.x = THREE.MathUtils.lerp(groupRef.current.position.x, targetX, 0.03);
      groupRef.current.position.y = THREE.MathUtils.lerp(groupRef.current.position.y, targetY, 0.03);
      groupRef.current.rotation.x = THREE.MathUtils.lerp(groupRef.current.rotation.x, -mouse.y * 0.4, 0.05);
      groupRef.current.rotation.y = THREE.MathUtils.lerp(groupRef.current.rotation.y, mouse.x * 0.4, 0.05);
      meshRef.current.rotation.z = state.clock.getElapsedTime() * 0.05;
    }
  });

  return (
    <Group ref={groupRef}>
      <Sphere ref={meshRef} args={[1.6, 64, 64]}>
        <MeshDistortMaterial
          color="#ffffff"
          speed={1.5}
          distort={0.15}
          radius={1}
          transparent
          opacity={0.1}
          metalness={0.2}
          roughness={0}
        />
        <FloatingCore />
      </Sphere>
    </Group>
  );
};

